# --- weighted means ---------------------------------------------------------

def test_weighted_means():
    report = _portfolio_report(
        _portfolio_group("region", ("green",), 1.0, 2.0)
    )
    data = {
        ("region", "r1"): _panel(
            (10.0, 100.0, 5.0), {"green": (-2.0, -10.0, 1.0)}
        ),
